import { useState, useEffect, useRef, useCallback } from "react";

interface ImageEntry {
  id: number;
  src: string;
  caption: string;
}

const IMAGES = [
  { id: 0, src: "data:image/jpeg;base64,", caption: "Opening Keynote" },
  { id: 1, src: "data:image/jpeg;base64,", caption: "Hackers at Work" },
  { id: 2, src: "data:image/jpeg;base64,", caption: "Sponsor Fair" },
  { id: 3, src: "data:image/jpeg;base64,", caption: "Check-In Desk" },
  { id: 4, src: "data:image/jpeg;base64,", caption: "KeanUHackThis 2026" },
  { id: 5, src: "data:image/jpeg;base64,", caption: "Team Collaboration" },
  { id: 6, src: "data:image/jpeg;base64,", caption: "API Workshop" },
  { id: 7, src: "data:image/jpeg;base64,", caption: "Table 18 in Action" },
  { id: 8, src: "data:image/jpeg;base64,", caption: "Sponsor Networking" },
  { id: 9, src: "data:image/jpeg;base64,", caption: "Workshop Audience" }
];

const TOTAL: number = IMAGES.length;
const LOCK_MS: number = 750;
const mod = (n: number, m: number): number => ((n % m) + m) % m;

// Inject crossfade keyframes once
if (typeof document !== "undefined" && !document.getElementById("sg-kf")) {
  const style = document.createElement("style");
  style.id = "sg-kf";
  style.textContent = `
    @keyframes fadeZoomOut {
      from { opacity: 1; transform: scale(1); }
      to   { opacity: 0; transform: scale(1.06); }
    }
    @keyframes fadeZoomIn {
      from { opacity: 0; transform: scale(0.96); }
      to   { opacity: 1; transform: scale(1); }
    }
  `;
  document.head.appendChild(style);
}

const EASE = "0.55s cubic-bezier(0.33,1,0.68,1)";
const CARD_W = 560;
const CARD_H = 360;

const s: Record<string, React.CSSProperties> = {
  root: {
    position: "relative",
    width: "100%",
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    fontFamily: "'Inter','Helvetica Neue',sans-serif",
    userSelect: "none",
    outline: "none",
    background: "transparent",
  },
  stage: {
    position: "relative",
    width: "100%",
    height: CARD_H + 60,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    cursor: "default",
  },
  track: {
    position: "relative",
    width: CARD_W,
    height: CARD_H,
  },
  wrapCenter: {
    position: "absolute",
    top: 0,
    left: 0,
    width: CARD_W,
    height: CARD_H,
    borderRadius: 16,
    overflow: "hidden",
    transformOrigin: "center center",
    transition: `transform ${EASE}, opacity ${EASE}, filter ${EASE}`,
    boxShadow: "0 24px 80px rgba(0,0,0,0.55), 0 0 0 1px rgba(255,255,255,0.07)",
    zIndex: 10,
    opacity: 1,
    transform: "translateX(0%) scaleX(1) scaleY(1) perspective(900px) rotateY(0deg)",
    filter: "none",
    cursor: "default",
    pointerEvents: "auto",
  },
  wrapSide: {
    position: "absolute",
    top: 0,
    left: 0,
    width: CARD_W,
    height: CARD_H,
    borderRadius: 16,
    overflow: "hidden",
    transformOrigin: "center center",
    transition: `transform ${EASE}, opacity ${EASE}, filter ${EASE}`,
    boxShadow: "0 24px 80px rgba(0,0,0,0.55), 0 0 0 1px rgba(255,255,255,0.07)",
    zIndex: 5,
    pointerEvents: "auto",
  },
  img: {
    position: "absolute",
    top: 0,
    left: 0,
    width: "100%",
    height: "100%",
    objectFit: "cover",
    display: "block",
  },
  imgOut: {
    zIndex: 2,
    animation: `fadeZoomOut ${LOCK_MS}ms ease forwards`,
  },
  imgIn: {
    zIndex: 1,
    animation: `fadeZoomIn ${LOCK_MS}ms ease forwards`,
  },
  veil: {
    position: "absolute",
    bottom: 0,
    left: 0,
    right: 0,
    height: "35%",
    background: "linear-gradient(to top, rgba(0,0,0,0.45) 0%, transparent 100%)",
    pointerEvents: "none",
    zIndex: 3,
  },
  dots: {
    display: "flex",
    gap: "0.45rem",
    marginTop: "1.4rem",
    zIndex: 10,
  },
  dot: {
    width: 6,
    height: 6,
    borderRadius: "50%",
    border: "none",
    background: "rgba(255,255,255,0.25)",
    cursor: "pointer",
    padding: 0,
    transition: "background 0.3s, transform 0.3s",
  },
  dotOn: {
    background: "rgba(255,255,255,0.9)",
    transform: "scale(1.6)",
  },
};

export default function SphereGallery(): React.JSX.Element {
  const [current, setCurrent] = useState<number>(0);
  const [prev, setPrev] = useState<number | null>(null);
  const [transitioning, setTransitioning] = useState<boolean>(false);
  const lockRef = useRef<boolean>(false);

  const navigate = useCallback(
    (dir: number): void => {
      if (lockRef.current) return;
      lockRef.current = true;
      setTransitioning(true);
      setPrev(current);
      setCurrent((c) => mod(c + dir, TOTAL));
      setTimeout(() => {
        setTransitioning(false);
        setPrev(null);
        lockRef.current = false;
      }, LOCK_MS);
    },
    [current]
  );

  useEffect(() => {
    const onKey = (e: KeyboardEvent): void => {
      if (e.key === "ArrowRight" || e.key === "ArrowDown") navigate(1);
      if (e.key === "ArrowLeft" || e.key === "ArrowUp") navigate(-1);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [navigate]);

  const slots = ([-1, 0, 1] as const).map((offset) => ({
    offset,
    img: IMAGES[mod(current + offset, TOTAL)],
  }));

  return (
    <div style={s.root} tabIndex={0}>
      <div style={s.stage}>
        <div style={s.track}>
          {slots.map(({ offset, img }) => {
            const isFront = offset === 0;
            const dir = offset as -1 | 0 | 1;

            const sideTransform: React.CSSProperties = isFront
              ? {}
              : {
                  transform: `translateX(${dir * 62}%) scaleX(0.60) scaleY(0.78) perspective(480px) rotateY(${dir * -44}deg)`,
                  opacity: 0.52,
                  filter: "brightness(0.48) blur(1.2px)",
                  cursor: "pointer",
                };

            return (
              <div
                key={offset}
                style={{ ...(isFront ? s.wrapCenter : s.wrapSide), ...sideTransform }}
                onClick={() => { if (offset !== 0) navigate(offset); }}
              >
                {/* Outgoing photo — fades out on top */}
                {isFront && transitioning && prev !== null && (
                  <img
                    src={IMAGES[prev].src}
                    alt=""
                    style={{ ...s.img, ...s.imgOut }}
                    draggable={false}
                  />
                )}
                {/* Current / incoming photo */}
                <img
                  src={img.src}
                  alt=""
                  style={{
                    ...s.img,
                    ...(isFront && transitioning ? s.imgIn : {}),
                  }}
                  draggable={false}
                />
                <div style={s.veil} />
              </div>
            );
          })}
        </div>
      </div>

      <nav style={s.dots} aria-label="Photo indicators">
        {IMAGES.map((_: ImageEntry, i: number) => (
          <button
            key={i}
            onClick={() => {
              const diff =
                mod(i - current + Math.round(TOTAL / 2), TOTAL) -
                Math.round(TOTAL / 2);
              if (diff !== 0) navigate(diff > 0 ? 1 : -1);
            }}
            style={{ ...s.dot, ...(i === current ? s.dotOn : {}) }}
            aria-label={`Photo ${i + 1}`}
          />
        ))}
      </nav>
    </div>
  );
}
